import { useState, useMemo, useCallback, type FormEvent, type ChangeEvent } from 'react';
import { Plus, Edit2, Trash2, ArrowUp, ArrowDown, RefreshCw, Loader2, Upload, ImageIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { Badge } from '@/components/ui/badge';
import I18nInput from '@/components/I18nInput';
import { useHeroSlides, type IHeroSlide } from '@/hooks/useHeroSlides';
import { useSiteImages } from '@/hooks/useSiteImages';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { batchTranslateI18n } from '@/lib/translate';
import { compressImage, formatFileSize, estimateBase64Size } from '@/lib/image-compress';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';
import { Image } from '@/components/ui/image';

interface SlideForm {
  badge: I18nText;
  title: I18nText;
  subtitle: I18nText;
  ctaText: I18nText;
  ctaLink: string;
  secondCtaText: I18nText;
  secondCtaLink: string;
  imageKey: string;
}

const emptyForm = (): SlideForm => ({
  badge: createI18nText(''),
  title: createI18nText(''),
  subtitle: createI18nText(''),
  ctaText: createI18nText(''),
  ctaLink: '/contact',
  secondCtaText: createI18nText(''),
  secondCtaLink: '/products',
  imageKey: 'hero_slide_1',
});

export default function AdminHeroSlidesPage() {
  const { adminT } = useI18n();
  const { slides, addSlide, updateSlide, deleteSlide, moveSlide, loading } = useHeroSlides();
  const { getImage } = useSiteImages();
  const { markDirty, syncModule, syncJsonFile, syncImagesInData, getStatus } = useSyncService();
  const syncStatus = getStatus('heroSlides');

  const [uploadingId, setUploadingId] = useState<string | null>(null);

  const handleReplaceImage = useCallback(
    async (id: string, file: File) => {
      if (!file.type.startsWith('image/')) {
        toast.error('Please upload a valid image file');
        return;
      }
      // 宽松的 10MB 上限（压缩后会小很多）
      if (file.size > 10 * 1024 * 1024) {
        toast.error('Image size must be under 10MB');
        return;
      }

      setUploadingId(id);
      const loadingToast = toast.loading(`Processing image: ${file.name}...`);

      try {
        // 压缩图片：宽高上限 1920×1080，JPEG 质量 0.8
        const compressed = await compressImage(file, {
          maxWidth: 1920,
          maxHeight: 1080,
          quality: 0.8,
          mimeType: 'image/jpeg',
        });

        const originalSize = file.size;
        const compressedSize = estimateBase64Size(compressed);
        const savedPct = Math.round((1 - compressedSize / originalSize) * 100);

        const ok = updateSlide(id, { image: compressed });

        if (!ok) {
          toast.dismiss(loadingToast);
          toast.error(
            'Storage full. The compressed image is still too large. Try a smaller image or delete unused custom images.',
            { duration: 6000 },
          );
          return;
        }

        toast.dismiss(loadingToast);
        toast.success(
          `Image updated (${formatFileSize(originalSize)} → ${formatFileSize(compressedSize)}, saved ${savedPct}%)`,
        );
        markDirty('heroSlides');
      } catch (err) {
        toast.dismiss(loadingToast);
        toast.error('Failed to process image: ' + String((err as Error)?.message || err));
      } finally {
        setUploadingId(null);
      }
    },
    [updateSlide],
  );

  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<SlideForm>(emptyForm());
  const [translatingAll, setTranslatingAll] = useState(false);
  const [translateProgress, setTranslateProgress] = useState({ current: 0, total: 0 });
  const [pageTranslating, setPageTranslating] = useState(false);
  const [pageProgress, setPageProgress] = useState({ current: 0, total: 0 });

  const openCreate = () => {
    setForm(emptyForm());
    setEditingId(null);
    setDialogOpen(true);
  };

  const openEdit = (slide: IHeroSlide) => {
    setForm({
      badge: slide.badge,
      title: slide.title,
      subtitle: slide.subtitle,
      ctaText: slide.ctaText,
      ctaLink: slide.ctaLink,
      secondCtaText: slide.secondCtaText,
      secondCtaLink: slide.secondCtaLink,
      imageKey: slide.imageKey,
    });
    setEditingId(slide.id);
    setDialogOpen(true);
  };

  const handleTranslateAllFields = async () => {
    const tasks = [
      { label: adminT('admin.badge'), value: form.badge },
      { label: adminT('admin.title'), value: form.title },
      { label: 'Subtitle', value: form.subtitle },
      { label: adminT('admin.primaryCta'), value: form.ctaText },
      { label: adminT('admin.secondaryCta'), value: form.secondCtaText },
    ].filter((t) => t.value.en.trim());

    if (tasks.length === 0) {
      toast.error('Please enter English text first');
      return;
    }

    setTranslatingAll(true);
    setTranslateProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total, label) => {
        setTranslateProgress({ current: cur, total });
        // 用 label 保持静默避免告警
        void label;
      });

      const newForm = { ...form };
      const formDict = newForm as unknown as Record<string, I18nText>;
      for (let i = 0; i < results.length; i++) {
        const r = results[i];
        const originalTask = tasks[i];
        if (!originalTask) continue;
        const key = originalTask.label;
        if (formDict[key]) {
          formDict[key] = r.value;
        }
      }
      setForm(newForm);

      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(
          `Translated ${successCount}/${results.length} fields. Failed: ${failed.map((f) => f.label).join(', ')}`,
        );
      } else {
        toast.success(`Translated ${successCount} fields to all languages`);
      }
    } catch {
      toast.error('Translation failed. Please try again.');
    } finally {
      setTranslatingAll(false);
      setTranslateProgress({ current: 0, total: 0 });
    }
  };

  /* ---------- 页面级：翻译所有 Slide ---------- */
  const handlePageTranslateAll = async () => {
    if (slides.length === 0) {
      toast.warning('No slides to translate');
      return;
    }
    const fieldNames: Array<'badge' | 'title' | 'subtitle' | 'ctaText' | 'secondCtaText'> = [
      'badge',
      'title',
      'subtitle',
      'ctaText',
      'secondCtaText',
    ];
    const tasks = slides.flatMap((s) =>
      fieldNames.map((f) => ({
        label: `Slide "${s.title.en.slice(0, 20)}" / ${f}`,
        value: s[f],
      })),
    ).filter((t) => t.value.en.trim());

    if (tasks.length === 0) {
      toast.warning('No English content found to translate');
      return;
    }

    setPageTranslating(true);
    setPageProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total) => {
        setPageProgress({ current: cur, total });
      });

      // 按顺序回填
      let resultIdx = 0;
      const newSlides = slides.map((s) => {
        const updated: IHeroSlide = { ...s };
        for (const f of fieldNames) {
          if (s[f].en.trim()) {
            if (results[resultIdx]) {
              updated[f] = results[resultIdx].value;
            }
            resultIdx++;
          }
        }
        return updated;
      });

      // 逐个更新（useHeroSlides 提供 updateSlide）
      for (const s of newSlides) {
        const original = slides.find((o) => o.id === s.id);
        if (original && JSON.stringify(original) !== JSON.stringify(s)) {
          updateSlide(s.id, s);
          markDirty('heroSlides');
        }
      }

      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(
          `Translated ${successCount}/${results.length} fields. ${failed.length} failed.`,
        );
      } else {
        toast.success(`Translation completed: ${successCount} fields translated`);
      }
    } catch {
      toast.error('Translation failed. Please try again.');
    } finally {
      setPageTranslating(false);
      setPageProgress({ current: 0, total: 0 });
    }
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.title.en.trim()) {
      toast.error('English title is required');
      return;
    }

    if (editingId) {
      updateSlide(editingId, {
        badge: form.badge,
        title: form.title,
        subtitle: form.subtitle,
        ctaText: form.ctaText,
        ctaLink: form.ctaLink.trim(),
        secondCtaText: form.secondCtaText,
        secondCtaLink: form.secondCtaLink.trim(),
        imageKey: form.imageKey,
      });
      markDirty('heroSlides');
      toast.success(adminT('admin.heroSlideUpdated'));
    } else {
      addSlide({
        badge: form.badge,
        title: form.title,
        subtitle: form.subtitle,
        ctaText: form.ctaText,
        ctaLink: form.ctaLink.trim(),
        secondCtaText: form.secondCtaText,
        secondCtaLink: form.secondCtaLink.trim(),
        imageKey: form.imageKey,
        image: '',
        order: slides.length + 1,
      });
      markDirty('heroSlides');
      toast.success(adminT('admin.heroSlideCreated'));
    }
    setDialogOpen(false);
    setForm(emptyForm());
  };

  const handleMove = (id: string, direction: 'up' | 'down') => {
    moveSlide(id, direction);
  };

  const handleDelete = (id: string) => {
    deleteSlide(id);
    markDirty('heroSlides');
    toast.success(adminT('admin.heroSlideDeleted'));
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-muted-foreground">Loading...</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[
          { label: adminT('admin.heroSlides') },
        ]}
      />

      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold">{adminT('admin.heroSlides')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.heroSlidesDesc')}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              syncModule('heroSlides', 'Hero Slides', async (config) => {
                const dataWithImages = await syncImagesInData(
                  config,
                  slides,
                  'hero',
                  ['image' as any]
                );
                await syncJsonFile(
                  config,
                  'data/hero-slides.json',
                  dataWithImages,
                  'Update hero slides data'
                );
              })
            }
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handlePageTranslateAll}
            disabled={pageTranslating || slides.length === 0}
            className="text-xs h-9"
          >
            {pageTranslating ? (
              <>
                <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                Translating {pageProgress.current}/{pageProgress.total}...
              </>
            ) : (
              <>
                <RefreshCw className="size-3.5 mr-1.5" />
                Translate All
              </>
            )}
          </Button>
          <Button onClick={openCreate} className="bg-primary hover:bg-primary/90">
            <Plus className="size-4 mr-2" />
            Add Slide
          </Button>
        </div>
      </div>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg">{slides.length} Slides</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="whitespace-nowrap w-16">{adminT('admin.sortOrder')}</TableHead>
                  <TableHead className="whitespace-nowrap w-24">{adminT('admin.preview')}</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.nameEn')}</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.badge')}</TableHead>
                  <TableHead className="whitespace-nowrap">{adminT('admin.cta')}</TableHead>
                  <TableHead className="whitespace-nowrap text-right">{adminT('admin.actions')}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {slides.map((slide, idx) => (
                  <TableRow key={slide.id}>
                    <TableCell className="text-sm text-muted-foreground tabular-nums">
                      {idx + 1}
                    </TableCell>
                    <TableCell>
                      <div className="relative w-24 h-14 rounded-md overflow-hidden border border-border group">
                        <Image
                          src={slide.image || getImage(slide.imageKey)}
                          alt={slide.title.en}
                          className="w-full h-full object-cover"
                        />
                        {uploadingId === slide.id && (
                          <div className="absolute inset-0 bg-black/70 flex flex-col items-center justify-center z-10">
                            <Loader2 className="size-5 text-white animate-spin mb-1" />
                            <span className="text-[10px] text-white/80">Compressing...</span>
                          </div>
                        )}
                        <label
                          className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center cursor-pointer transition-opacity gap-0.5"
                          title="Replace image"
                        >
                          <Upload className="size-4 text-white" />
                          <span className="text-[10px] text-white font-medium">Replace</span>
                          <input
                            type="file"
                            accept="image/*"
                            className="hidden"
                            disabled={uploadingId === slide.id}
                            onChange={(e: ChangeEvent<HTMLInputElement>) => {
                              const file = e.target.files?.[0];
                              if (file) handleReplaceImage(slide.id, file);
                              e.target.value = '';
                            }}
                          />
                        </label>
                      </div>
                      <div className="flex items-center gap-1 mt-1.5">
                        {slide.image ? (
                          <span className="text-[10px] text-primary">Custom</span>
                        ) : (
                          <span className="text-[10px] text-muted-foreground">Default</span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="font-medium max-w-xs">
                      <div className="truncate">{slide.title.en}</div>
                      <div className="text-xs text-muted-foreground truncate mt-0.5">
                        {slide.subtitle.en}
                      </div>
                    </TableCell>
                    <TableCell>
                      {slide.badge.en ? (
                        <Badge variant="outline" className="text-xs">
                          {slide.badge.en}
                        </Badge>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </TableCell>
                    <TableCell className="text-sm max-w-[180px]">
                      <div className="truncate font-medium">{slide.ctaText.en || '—'}</div>
                      <div className="text-xs text-muted-foreground truncate">
                        {slide.ctaLink}
                      </div>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-1">
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-7 w-7"
                          disabled={idx === 0}
                          onClick={() => handleMove(slide.id, 'up')}
                          title="Move up"
                        >
                          <ArrowUp className="size-3.5" />
                        </Button>
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-7 w-7"
                          disabled={idx === slides.length - 1}
                          onClick={() => handleMove(slide.id, 'down')}
                          title="Move down"
                        >
                          <ArrowDown className="size-3.5" />
                        </Button>
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-7 w-7"
                          onClick={() => openEdit(slide)}
                          title="Edit"
                        >
                          <Edit2 className="size-3.5" />
                        </Button>
                        <AlertDialog>
                          <AlertDialogTrigger asChild>
                            <Button
                              size="icon"
                              variant="ghost"
                              className="h-7 w-7 text-destructive hover:text-destructive"
                              title="Delete"
                            >
                              <Trash2 className="size-3.5" />
                            </Button>
                          </AlertDialogTrigger>
                          <AlertDialogContent>
                            <AlertDialogHeader>
                              <AlertDialogTitle>Delete Hero Slide?</AlertDialogTitle>
                              <AlertDialogDescription>
                                This action cannot be undone. The slide will be removed from the homepage carousel.
                              </AlertDialogDescription>
                            </AlertDialogHeader>
                            <AlertDialogFooter>
                              <AlertDialogCancel>{adminT('admin.cancel')}</AlertDialogCancel>
                              <AlertDialogAction
                                onClick={() => handleDelete(slide.id)}
                                className="bg-destructive hover:bg-destructive/90"
                              >
                                Delete
                              </AlertDialogAction>
                            </AlertDialogFooter>
                          </AlertDialogContent>
                        </AlertDialog>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
                {slides.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={6} className="text-center py-10 text-muted-foreground">
                      No hero slides yet. Click "Add Slide" to create one.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center justify-between flex-wrap gap-2">
              <span>{editingId ? adminT('admin.editHeroSlide') : adminT('admin.addHeroSlide')}</span>
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={handleTranslateAllFields}
                disabled={translatingAll}
                className="text-xs h-8"
              >
                {translatingAll ? (
                  <>
                    <Loader2 className="size-3.5 mr-1 animate-spin" />
                    Translating {translateProgress.current}/{translateProgress.total}...
                  </>
                ) : (
                  <>
                    <RefreshCw className="size-3.5 mr-1" />
                    Translate All
                  </>
                )}
              </Button>
            </DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-5">
            <I18nInput
              label="Badge Text"
              value={form.badge}
              onChange={(v) => setForm({ ...form, badge: v })}
              placeholder="LED Security Light Manufacturer"
            />
            <I18nInput
              label="Headline Title"
              value={form.title}
              onChange={(v) => setForm({ ...form, title: v })}
              placeholder="Your Trusted Lighting Supplier"
            />
            <I18nInput
              label="Subtitle"
              value={form.subtitle}
              onChange={(v) => setForm({ ...form, subtitle: v })}
              placeholder="Brief description under the headline"
              multiline
              rows={3}
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <I18nInput
                label="Primary CTA Text"
                value={form.ctaText}
                onChange={(v) => setForm({ ...form, ctaText: v })}
                placeholder="Get Quote"
                />
              <div className="space-y-2">
                <label className="text-sm font-medium">Primary CTA Link</label>
                <Input
                  value={form.ctaLink}
                  onChange={(e) => setForm({ ...form, ctaLink: e.target.value })}
                  placeholder="/contact"
                />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <I18nInput
                label="Secondary CTA Text"
                value={form.secondCtaText}
                onChange={(v) => setForm({ ...form, secondCtaText: v })}
                placeholder="View Products"
                />
              <div className="space-y-2">
                <label className="text-sm font-medium">Secondary CTA Link</label>
                <Input
                  value={form.secondCtaLink}
                  onChange={(e) => setForm({ ...form, secondCtaLink: e.target.value })}
                  placeholder="/products"
                />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Background Image Key</label>
              <Input
                value={form.imageKey}
                onChange={(e) => setForm({ ...form, imageKey: e.target.value })}
                placeholder="hero_slide_1"
              />
              <p className="text-xs text-muted-foreground">
                Available keys: hero_slide_1, hero_slide_2, hero_slide_3. Go to Images page to upload custom hero images.
              </p>
            </div>
            <DialogFooter className="pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => setDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit" className="bg-primary hover:bg-primary/90">
                {editingId ? adminT('admin.edit') : 'Add Slide'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
